#!/usr/bin/env python3
"""Apply a first full-NT TR literal revision pass to the imported source CSV."""

from __future__ import annotations

import argparse
import csv
import json
import re
from collections import Counter, defaultdict
from functools import lru_cache
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
DEFAULT_SOURCE = ROOT / "data" / "raw" / "tr_greek" / "nt_full.csv"
DEFAULT_REPORT = ROOT / "output" / "nt_tr_literal_revision_pass1_diagnostics.json"
DEFAULT_REVIEW_QUEUE = ROOT / "output" / "nt_tr_literal_revision_review_queue.csv"
REVIEW_DIR = ROOT / "data" / "research"

REVIEW_COLUMNS = ["ukjv_translation", "review_status", "review_notes"]
RESOLVED_REVIEW_STATUSES = {"keep", "revised"}
REVIEW_PASS_RE = re.compile(r"nt_review_pass_(\d+)\.md$")
STRONGS_MARKER_RE = re.compile(r"\s*\([a-z]\.\s*[^)]*\)")
SPACE_RE = re.compile(r"\s+")
SPACE_BEFORE_PUNCT_RE = re.compile(r"\s+([,.;:?!])")
SENTENCE_JOIN_RE = re.compile(r"([.!?])([A-Z])")
LITERAL_TOKEN_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9']*")
CHAR_CLASS_RE = re.compile(r"\[[^\]]*\]")
REGEX_ESCAPE_RE = re.compile(r"\\(?:[bBAZdDsSwW]|[sS][*+]?)")
IGNORECASE_FLAG = int(re.I)


@lru_cache(maxsize=None)
def cached_regex(pattern: str, flags: int = 0) -> re.Pattern[str]:
    return re.compile(pattern, flags)


@lru_cache(maxsize=10000)
def folded_text(text: str) -> str:
    return text.casefold()


@lru_cache(maxsize=None)
def folded_literal(text: str) -> str:
    return text.casefold()


@lru_cache(maxsize=None)
def required_literal_token(pattern: str) -> str:
    if "|" in pattern:
        return ""
    simplified = CHAR_CLASS_RE.sub(" ", pattern)
    simplified = REGEX_ESCAPE_RE.sub(" ", simplified)
    simplified = (
        simplified.replace(r"\.", ".")
        .replace(r"\,", ",")
        .replace(r"\;", ";")
        .replace(r"\:", ":")
        .replace(r"\?", "?")
        .replace(r"\!", "!")
        .replace(r"\'", "'")
        .replace(r"\"", '"')
    )
    tokens = [token for token in LITERAL_TOKEN_RE.findall(simplified) if len(token) > 1]
    if not tokens:
        return ""
    return max(tokens, key=len)


@lru_cache(maxsize=None)
def literal_precheck(pattern: str, flags: int = 0) -> tuple[str, bool]:
    ignore_case = bool(flags) and (int(flags) & IGNORECASE_FLAG) != 0
    token = required_literal_token(pattern)
    if ignore_case:
        token = folded_literal(token)
    return token, ignore_case

