def greek_has_stem(greek: str, *stems: str) -> bool:
    return any(cached_regex(rf"(?<!\S){re.escape(stem)}\w*").search(greek) for stem in stems)


def greek_has_token_part(greek: str, *parts: str) -> bool:
    return any(cached_regex(rf"(?<!\S)\w*{re.escape(part)}\w*").search(greek) for part in parts)


def greek_has_phrase(greek: str, phrase: str) -> bool:
    return cached_regex(rf"(?<!\S){re.escape(phrase)}(?!\S)").search(greek) is not None


def load_rows(path: Path) -> tuple[list[dict[str, str]], list[str]]:
    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle)
        return list(reader), list(reader.fieldnames or [])


def write_rows(path: Path, rows: list[dict[str, str]], fieldnames: list[str]) -> None:
    for column in REVIEW_COLUMNS:
        if column not in fieldnames:
            fieldnames.append(column)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames, lineterminator="\n")
        writer.writeheader()
        for row in rows:
            writer.writerow({field: row.get(field, "") for field in fieldnames})


def review_pass_sort_key(path: Path) -> tuple[int, str]:
    match = REVIEW_PASS_RE.search(path.name)
    return (int(match.group(1)), path.name) if match else (0, path.name)


def load_latest_review_statuses() -> dict[str, str]:
    statuses: dict[str, str] = {}
    for path in sorted(REVIEW_DIR.glob("nt_review_pass_*.md"), key=review_pass_sort_key):
        ref = ""
        for raw in path.read_text(encoding="utf-8").splitlines():
            line = raw.strip()
            if line.startswith("## "):
                ref = line[3:].strip()
            elif ref and line.startswith("- status:"):
                match = re.search(r"`([^`]+)`", line)
                statuses[ref] = match.group(1) if match else line.split(":", 1)[1].strip()
    return statuses


def replace_literal(
    text: str,
    pattern: str,
    replacement: str,
    note: str,
    notes: list[str],
    *,
    flags: int = 0,
) -> str:
    token, ignore_case = literal_precheck(pattern, flags)
    if token and token not in (folded_text(text) if ignore_case else text):
        return text
    new_text, count = cached_regex(pattern, flags).subn(replacement, text)
    if count:
        notes.append(note)
    return new_text


def replace_word(text: str, old: str, new: str, note: str, notes: list[str]) -> str:
    if folded_literal(old) not in folded_text(text):
        return text
    pattern = cached_regex(rf"\b{re.escape(old)}\b", re.I)

    def repl(match: re.Match[str]) -> str:
        value = match.group(0)
        if value.isupper():
            return new.upper()
        if value[0].isupper():
            return new[:1].upper() + new[1:]
        return new

    new_text, count = pattern.subn(repl, text)
    if count:
        notes.append(note)
    return new_text


def replace_word_fixed(text: str, old: str, new: str, note: str, notes: list[str]) -> str:
    if folded_literal(old) not in folded_text(text):
        return text
    pattern = cached_regex(rf"\b{re.escape(old)}\b", re.I)
    new_text, count = pattern.subn(new, text)
    if count:
        notes.append(note)
    return new_text


def apply_proper_name_revisions(row: dict[str, str], text: str, notes: list[str]) -> str:
    for old, new in NT_CONTEXTUAL_PROPER_NAME_REPLACEMENTS.get(row.get("ref", ""), []):
        text = replace_word_fixed(text, old, new, "standardized contextual NT proper-name English equivalent", notes)
    for old, new in NT_PROPER_NAME_REPLACEMENTS:
        text = replace_word_fixed(text, old, new, "standardized NT proper-name English equivalent", notes)
    text = replace_word_fixed(text, "Sabaoth", "hosts", "translated sabaoth as hosts", notes)
    text = replace_word_fixed(text, "Juda", "Judah", "standardized Juda as Judah in tribe/land contexts", notes)
    return text


def clean_spacing(text: str) -> str:
    text = SPACE_RE.sub(" ", text).strip()
    text = SPACE_BEFORE_PUNCT_RE.sub(r"\1", text)
    text = SENTENCE_JOIN_RE.sub(r"\1 \2", text)
    text = cached_regex(r"\bA overseer\b").sub("An overseer", text)
    text = cached_regex(r"\ba overseer\b").sub("an overseer", text)
    return text


